/* Rule-based guidance. No LLM, no inferred legal eligibility, no external calls. */
(function(){
 const modeButtons=[...document.querySelectorAll('[data-nav-mode]')];
 const result=document.getElementById('nav-result');
 const el=(id)=>document.getElementById(id);
 const safe=(s)=>String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
 const roles={seafarer:['J1','J2','J3','J4','J5','J6','J13','J14','J15','J16','J17','J18','J20','J21','J23','J24'],officer:['J7','J8','J9','J10','J11','J12','J19','J22']};
 for(const [kind,ids] of Object.entries(roles)){
   const select=el(kind==='seafarer'?'nav-seafarer-job':'nav-officer-job');
   select.innerHTML='<option value="">اختر الوظيفة</option>'+ids.map(id=>`<option value="${id}">${safe(JOB[id].name)}</option>`).join('');
 }
 function changeMode(mode){
   modeButtons.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.navMode===mode)));
   document.querySelectorAll('[data-nav-pane]').forEach(p=>p.hidden=p.dataset.navPane!==mode);
   result.hidden=true;
 }
 modeButtons.forEach(b=>b.addEventListener('click',()=>changeMode(b.dataset.navMode)));
 const disclaimer='النتائج استرشادية مأخوذة من المصفوفة المرفقة ولا تثبت أهلية المتقدم، ولا تعني أن الدورة متاحة أو معتمدة؛ ينبغي مراجعة الشروط والمستندات والتطبيق لدى الجهات المختصة. بعض المراجع معلّمة في المصدر «للتحقق». ';
 function showCourses(courses){return courses.slice(0,18).map(c=>`<div class="nav-course"><strong>${safe(c.ar)}</strong><small dir="ltr">${safe(c.en)}</small><small>${safe(c.stcw)} · ${safe(c.phase)} · ${safe(c.conf)}</small></div>`).join('')}
 function showJob(jobId,options={}){
   const j=JOB[jobId];if(!j)return;
   const qualified=options.qualification;
   const linked=D.courses.filter(c=>c.jobs[jobId]);
   let chosen=linked;
   if(options.focus==='specialist')chosen=linked.filter(c=>!isQ(c.jobs[jobId])&&c.jobs[jobId]!=='اتفاقية');
   if(options.focus==='simulator')chosen=linked.filter(c=>c.sim==='نعم'||c.sim==='اختياري');
   if(options.aim==='next'&&j.next.length){chosen=D.courses.filter(c=>j.next.some(id=>c.jobs[id]));}
   const title=options.aim==='next'&&j.next.length?'دورات الوظائف التالية المقترحة':'دورات مرتبطة بالوظيفة';
   let qualMsg='';
   if(qualified)qualMsg='<p class="nav-warning">المؤهل المختار: <strong>'+safe(qualified)+'</strong>. لا يمكن الجزم بقبول هذا المؤهل وحده؛ راجع اشتراطات الوظيفة ونوع المؤهل والسن والخدمة البحرية.</p>';
   result.innerHTML=`<h3 class="nav-result-title">${safe(j.name)} — ${title}</h3><div class="nav-steps"><span class="nav-step">${safe(j.dept)}</span><span class="nav-step">${safe(j.entry)}</span></div><p><strong>المسار التالي:</strong> ${safe(j.nextNote)}</p>${qualMsg}<p class="nav-hint">${chosen.length} دورة/وحدة مرتبطة بحسب معيار البحث. تصنيف الإلزام يُراجع داخل المصفوفة.</p>${chosen.length?`<div class="nav-course-list">${showCourses(chosen)}</div>`:'<p class="nav-warning">لا توجد دورات مطابقة للمرشح المختار في المصفوفة.</p>'}<div class="nav-links"><button type="button" data-go-job="${safe(jobId)}">فتح المسار التفصيلي</button><button type="button" data-go-matrix="1">فتح المصفوفة الكاملة</button></div><p class="nav-warning">${disclaimer}</p>`;
   result.hidden=false;
 }
 document.querySelectorAll('[data-guide]').forEach(form=>form.addEventListener('submit',e=>{
   e.preventDefault();if(!form.reportValidity())return;
   const kind=form.dataset.guide;
   if(kind==='beginner'){
     const qual=el('nav-qualification').selectedOptions[0].textContent;
     showJob(el('nav-beginner-track').value,{qualification:qual});
   }else if(kind==='seafarer')showJob(el('nav-seafarer-job').value,{aim:el('nav-seafarer-aim').value});
   else if(kind==='officer')showJob(el('nav-officer-job').value,{focus:el('nav-officer-focus').value});
   else {
     const q=el('nav-course-query').value.trim().toLowerCase();
     const courses=D.courses.filter(c=>[c.ar,c.en,c.stcw,c.mc,c.cat,c.eg].join(' ').toLowerCase().includes(q));
     result.innerHTML=`<h3 class="nav-result-title">نتائج البحث: ${courses.length}</h3>${courses.length?`<div class="nav-course-list">${showCourses(courses)}</div>`:'<p>لم نعثر على دورة مطابقة؛ جرّب الاسم أو الاختصار أو مرجع STCW.</p>'}<div class="nav-links"><button type="button" data-go-matrix="1">البحث المتقدم في المصفوفة</button></div><p class="nav-warning">${disclaimer}</p>`;
     result.hidden=false;
   }
   result.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'nearest'});
 }));
 result.addEventListener('click',e=>{
   const btn=e.target.closest('button');if(!btn)return;
   if(btn.dataset.goJob){selectJob(btn.dataset.goJob,false);el('p-paths').scrollIntoView({behavior:'smooth',block:'start'})}
   if(btn.dataset.goMatrix){showTab('tab-matrix');el('p-matrix').scrollIntoView({behavior:'smooth',block:'start'})}
 });
})();
